INSERT INTO events (date, titleEn, titleAr, category, severity, descriptionEn, descriptionAr, impact, source) VALUES ('2011-01-27', 'First Major Anti-Government Protests in Sana''a', 'أولى المظاهرات الكبرى المناهضة للحكومة في صنعاء', 'political', 'medium', 'Inspired by the Arab Spring, thousands of protesters, mainly students and activists, took to the streets of Sana''a, demanding the resignation of President Ali Abdullah Saleh and an end to his 33-year rule.', 'اندلعت آلاف المظاهرات، مستوحاة من الربيع العربي، بقيادة الطلاب والنشطاء في شوارع صنعاء، مطالبين باستقالة الرئيس علي عبد الله صالح وإنهاء حكمه الذي دام 33 عامًا.', 'Marked the beginning of the Yemeni Revolution, escalating political instability and civil unrest across the country.', 'Al Jazeera, BBC News, Human Rights Watch');
INSERT INTO events (date, titleEn, titleAr, category, severity, descriptionEn, descriptionAr, impact, source) VALUES ('2011-02-02', 'President Saleh Offers Concessions to Halt Protests', 'الرئيس صالح يقدم تنازلات لوقف الاحتجاجات', 'policy', 'medium', 'In an attempt to defuse the growing crisis, President Saleh announced he would not seek re-election in 2013 and would not hand power to his son, a major demand of the opposition.', 'في محاولة لنزع فتيل الأزمة المتصاعدة، أعلن الرئيس صالح أنه لن يسعى لإعادة انتخابه في عام 2013 ولن يسلم السلطة لابنه، وهو مطلب رئيسي للمعارضة.', 'Temporarily eased tensions but was largely rejected by the opposition, who viewed it as insufficient and continued to demand his immediate departure.', 'Reuters, The Guardian');
INSERT INTO events (date, titleEn, titleAr, category, severity, descriptionEn, descriptionAr, impact, source) VALUES ('2011-03-18', 'Friday of Dignity Massacre in Sana''a', 'مجزرة جمعة الكرامة في صنعاء', 'security', 'critical', 'Unidentified gunmen, widely believed to be government loyalists, opened fire on peaceful anti-government protesters at Change Square in Sana''a. The attack was a turning point in the uprising.', 'فتح مسلحون مجهولون، يُعتقد على نطاق واسع أنهم موالون للحكومة، النار على متظاهرين سلميين مناهضين للحكومة في ساحة التغيير بصنعاء. شكل الهجوم نقطة تحول في الانتفاضة.', 'At least 52 protesters were killed and over 200 wounded. The event led to mass defections from the military and government, including key tribal leaders and ambassadors.', 'Amnesty International, Human Rights Watch')

